INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (0, "", "vo_travel_talk_20017_01", 21, "", 20172, "", 0, "vo_travel_talk", 1201720009, "");
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (10, 0, "あ、相変わらずのケンカバカですね……\nあたしはこんな面倒な仕事放り出して、\nさっさとランドソルに帰りてーですよ。", 11, 0, 20172, 0, 1, 106611, 1201720010, 1);
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES ("", "", "", 91, "", 20172, "", "", 0, 1201720011, "");
